import{_ as e,Y as d,o,c as a,aA as n,H as i}from"./chunks/framework.C6iXY4oq.js";import"./chunks/theme.DxPpgtNj.js";const f=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/guide/home.md","filePath":"zh-cn/guide/home.md"}'),l={name:"zh-cn/guide/home.md"};function s(c,t,h,p,u,g){const r=d("NolebaseGitChangelog");return o(),a("div",null,[t[0]||(t[0]=n('<h1 id="introduction" tabindex="-1">介绍 <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><blockquote><p>这是一个 Android 通知图标适配计划，为不符合 Android 原生通知设计的应用与厂商系统提供规范的单色图标资源。</p></blockquote><h2 id="background" tabindex="-1">背景 <a class="header-anchor" href="#background" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>这个项目设立的初衷是为了规范混乱的第三方应用生态，让第三方应用的通知图标也能按照原生 Android 通知图标的规范进行设计。</p><p>这一切的原因归根结底其实是当初 MIUI 不规范的小米推送通知图标导致的生态割裂问题，其他厂商也没有完全解决这个问题，而是普遍采用了 Apple 方案使用应用的桌面图标作为主要通知图标这种欺骗意义上的 “解决方案”，或者是 vivo 采用的自己维护一套单色通知图标的方案，但是在后来的 OriginOS 中也逐步放弃了。</p><p>作为这个项目的负责人，我的观点是，这个问题的责任在 Google，Android 明确规定了通知图标的设计规范，但 Google 并没有对厂商进行强制约束，导致厂商可以随意破坏原生通知图标的设计规范。</p><p>最后甚是可笑的是，Google 也在 Android 16 放弃了强制着色通知图标的设计规范，并在通知面板中将通知图标设置成了应用的桌面图标，完成了对生态的全面妥协。</p><p>这个从 2022 年开始启动的项目原名叫 <strong>AndroidNotifyIconAdapt</strong>，当年这个四不像的名字也一度导致项目空有资源但没有规范，现在它正式更名为 <strong>Android Notification Icon Project</strong> (代号为 <strong>ANIP</strong>)，并对原始的图标资源规则进行了全面改版，项目后期将全面投入更现代的持续社区维护中。</p><p>项目已由原 <strong>AGPL-3.0</strong> 许可协议调整至 <strong>Apache-2.0</strong>，ANIP 将以当前协议继续对外开放，任何人都可以在遵守协议的前提下使用、修改、分发本项目的资源，协议的变更不自动适用于之前的版本。</p><h2 id="usage" tabindex="-1">用途 <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>ANIP 目前采用社区配套的 Xposed 模块方案对系统界面 (System UI) 进行适配，并提供了依赖社区维护的第三方应用、游戏、系统应用的单色通知图标资源与规则。</p><p>目前 ANIP 的支持路线如下，后期我们会将这些 Xposed 模块整合为一个聚合型模块统一进行适配并由 <a href="https://github.com/BetterAndroid" target="_blank" rel="noreferrer">BetterAndroid</a> 组织管理。</p><ol><li>可直接使用的 Xposed 模块</li></ol><ul><li>HyperOS/MIUI 系统请参阅 <a href="https://github.com/fankes/MIUINativeNotifyIcon" target="_blank" rel="noreferrer">MIUI 原生通知图标</a></li><li>ColorOS、Realme UI、OxygenOS (≥12) 系统请参阅 <a href="https://github.com/fankes/ColorOSNotifyIcon" target="_blank" rel="noreferrer">ColorOS 通知图标增强</a></li></ul><ol start="2"><li>社区提出的适配需求</li></ol><ul><li>类原生、Pixel 用户请参阅 <a href="https://github.com/BetterAndroid/android-notification-icon-project/issues/102" target="_blank" rel="noreferrer">此 Issue</a></li><li>Flyme 用户请参阅 <a href="https://github.com/BetterAndroid/android-notification-icon-project/issues/201" target="_blank" rel="noreferrer">此 Issue</a></li><li>OneUI 用户请参阅 <a href="https://github.com/BetterAndroid/android-notification-icon-project/issues/475" target="_blank" rel="noreferrer">此 Issue</a></li></ul><p>ANIP 提供了图标资源下载与应用的 <a href="./../sdk/quick-start">官方 SDK</a>，你可以使用这套 SDK 构建自己的 Xposed 模块或通知适配方案。</p><p>如果你是用户，你可以下载并体验 <a href="https://github.com/BetterAndroid/android-notification-icon-project/blob/main/sdk/samples/demo/release" target="_blank" rel="noreferrer">ANIP 演示</a>。</p><h2 id="noncompliant-systems" tabindex="-1">不规范公示 <a class="header-anchor" href="#noncompliant-systems" aria-label="Permalink to &quot;不规范公示&quot;">​</a></h2><table tabindex="0"><thead><tr><th>系统</th><th>版本</th><th>破坏方式</th></tr></thead><tbody><tr><td>原生 Android</td><td>≥ 16</td><td>通知中心替换为应用图标</td></tr><tr><td>EMUI</td><td>4.0、4.0.1、4.1</td><td>全部替换为应用图标</td></tr><tr><td>HarmonyOS</td><td>≥ 4.0</td><td>全部替换为应用图标</td></tr><tr><td>ColorOS<br>OxygenOS</td><td>≥ 15.0.1</td><td>全部替换为应用图标</td></tr><tr><td>RealmeUI</td><td>≥ 6.0</td><td>全部替换为应用图标</td></tr><tr><td>MIUI</td><td>≤ 9、≥ 12.5</td><td>全部替换为应用图标</td></tr><tr><td>HyperOS</td><td>全部</td><td>系统应用白名单、第三方应用替换为应用图标</td></tr><tr><td>OneUI</td><td>≥ 6.0</td><td>通知中心替换为应用图标 (可关闭)</td></tr><tr><td>ZUI</td><td>全部</td><td>全部替换为应用图标</td></tr><tr><td>Nubia UI</td><td>全部</td><td>全部替换为应用图标</td></tr><tr><td>RedMagicOS</td><td>全部</td><td>全部替换为应用图标</td></tr><tr><td>360 OS</td><td>全部</td><td>全部替换为应用图标</td></tr><tr><td>CoolOS</td><td>全部</td><td>全部替换为应用图标</td></tr><tr><td>WaterOS</td><td>全部</td><td>全部替换为应用图标</td></tr><tr><td>Flyme</td><td>全部</td><td>系统与第三方应用白名单</td></tr><tr><td>OriginOS</td><td>≥ 6</td><td>全部替换为应用图标</td></tr></tbody></table><h2 id="contribution" tabindex="-1">功能贡献 <a class="header-anchor" href="#contribution" aria-label="Permalink to &quot;功能贡献&quot;">​</a></h2><p>本项目的维护离不开各位开发者的支持和贡献，如果可能，欢迎提交 PR 为此项目贡献你认为需要的功能或前往 <a href="https://github.com/BetterAndroid/android-notification-icon-project/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 向我们提出建议。</p>',22)),i(r)])}const I=e(l,[["render",s]]);export{f as __pageData,I as default};
